      const grid=base.gridSizeMm,id=`edited:${uid()}`;commit({...draft,walls:[...draft.walls,{id,ax:a.x/grid,az:a.z/grid,bx:end.x/grid,bz:end.z/grid}]});setSelected(id);setMode('select');
